function draw(g, t) {
  g.clear('#10131a');
  g.fill('#6f8cff');
  const r = 24 + Math.sin(t * 2) * 8;
  g.circle(g.width / 2, g.height / 2, r);
}
`},{id:"particles",name:"Particles",description:"Glowing dots that drift upwards and shy away from the pointer.",code:`// Anything declared outside draw() keeps its value between frames
const dots = [];

function setup(g) {
  for (let i = 0; i < 80; i++) {
    dots.push({
      x: g.random(g.width),
      y: g.random(g.height),
      r: g.random(1.5, 4),
      speed: g.random(8, 30),
      hue: g.random(190, 280),
    });
  }
}

function draw(g, t, dt) {
  g.clear('#0b0e17');
  g.blend('add');
  for (const d of dots) {
    d.y -= d.speed * dt;
    if (d.y < -10) { d.y = g.height + 10; d.x = g.random(g.width); }
    // Push dots away from the pointer
    if (g.pointer.inside) {
      const dx = d.x - g.pointer.x;
      const dy = d.y - g.pointer.y;
      const dist = Math.hypot(dx, dy) || 1;
      if (dist < 70) { d.x += (dx / dist) * (70 - dist) * 4 * dt; d.y += (dy / dist) * (70 - dist) * 4 * dt; }
    }
    g.fill(g.hsl(d.hue, 90, 65, 0.8));
    g.circle(d.x + Math.sin(t + d.hue) * 6, d.y, d.r);
  }
}
